var RIF_PASSOS = {"quant": [["O que a questão quer?", "Reescrever o que a questão quer que eu responda"], ["O que eu tenho?", "Separar dados: números, medidas e unidades"], ["Qual é o desenho?", "Escolher estratégia ou estimar o resultado"], ["Minha solução", "Equacionar, calcular e comparar com as alternativas"], ["Confiro e respondo", "Conferir se o número faz sentido, comparar e marcar uma ou mais alternativas"]], "qual": [["O que a questão quer?", "Reescrever o que a questão quer que eu interprete"], ["O que eu tenho?", "Separar evidências do texto, da imagem e da fonte"], ["Como eu separo as afirmações?", "Propor uma leitura com base nas evidências"], ["Julgo uma por uma", "Confrontar cada alternativa com as evidências"], ["Confiro e respondo", "Marcar e justificar em uma frase"]]};
